import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  poweredByHeader: false,
  async headers() {
    return [
      {
        source: "/:path*",
        headers: [
          { key: "X-Content-Type-Options", value: "nosniff" },
          { key: "X-Frame-Options", value: "DENY" },
          { key: "Referrer-Policy", value: "no-referrer" },
          {
            key: "Permissions-Policy",
            value: "camera=(), microphone=(), geolocation=()"
          }
        ]
      }
    ];
  }
};

export default nextConfig;

{
  "openapi": "3.1.0",
  "info": {
    "title": "AgentResolver API",
    "version": "0.1.0",
    "description": "Free capability resolution across AgentResolver-owned capabilities, live MCP directories, and x402 marketplace services."
  },
  "servers": [
    { "url": "https://agentresolver.vercel.app" }
  ],
  "paths": {
    "/api/resolve": {
      "post": {
        "operationId": "resolveCapability",
        "summary": "Resolve a natural-language goal to machine capabilities",
        "description": "Resolution is free. The resolver searches AgentResolver-owned capabilities, privacy-safe live MCP directory matches, and x402 marketplace services. Arbitrary goal text is not forwarded to MCP directories; only locally derived generic capability terms may be used for third-party MCP search.",
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "required": ["goal"],
                "properties": {
                  "goal": { "type": "string", "maxLength": 1000 },
                  "url": { "type": "string", "format": "uri", "maxLength": 2048 },
                  "limit": { "type": "integer", "minimum": 1, "maximum": 10, "default": 3 }
                }
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": "Resolution containing owned, mcp, and marketplace match arrays"
          },
          "400": { "description": "Invalid input" }
        }
      }
    },
    "/api/execute": {
      "post": {
        "operationId": "executeCapability",
        "summary": "Resolve the direct endpoint for a free capability; generic paid execution is disabled",
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "required": ["capabilityId"],
                "properties": {
                  "capabilityId": { "type": "string" },
                  "input": {}
                }
              }
            }
          }
        },
        "responses": {
          "200": { "description": "Direct endpoint guidance for a free capability" },
          "404": { "description": "Unknown capability" },
          "503": {
            "description": "Capability is not live or generic paid execution is intentionally disabled"
          }
        }
      }
    }
  }
}

import { NextResponse } from "next/server";

const catalog = {
  specVersion: "1.0",
  host: {
    displayName: "AgentResolver",
    identifier: "agentresolver.vercel.app",
    documentationUrl: "https://agentresolver.vercel.app"
  },
  entries: [
    {
      identifier: "urn:air:agentresolver.vercel.app:mcp:agentresolver",
      displayName: "AgentResolver",
      type: "application/mcp-server-card+json",
      url: "https://agentresolver.vercel.app/mcp/server-card",
      description:
        "Free machine-first capability resolver for autonomous agents with live x402 service discovery.",
      capabilities: [
        "CapabilityResolver",
        "ToolDiscovery",
        "MCPDiscovery",
        "X402Discovery",
        "APISelection",
        "MachineServiceRouting"
      ],
      tags: [
        "agents",
        "mcp",
        "x402",
        "tool-discovery",
        "api-discovery",
        "routing"
      ],
      version: "0.1.0",
      representativeQueries: [
        "find a tool or API that can complete this task",
        "find an MCP server for this capability",
        "find a machine-payable x402 service for this job",
        "compare external services that can satisfy my goal",
        "what tool should my agent use next"
      ]
    }
  ]
};

export function GET() {
  return NextResponse.json(catalog, {
    headers: {
      "cache-control": "public, max-age=300",
      "access-control-allow-origin": "*"
    }
  });
}

